  FT["SG-H1942"] = {"id":"SG-H1942","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S602-2025?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Boardroom 私人有限公司依第 13（12）条享有的豁免）命令 2025","en":"Income Tax (Boardroom Pte. Ltd. — Section 13(12) Exemption) Order 2025","orig":"Income Tax (Boardroom Pte. Ltd. — Section 13(12) Exemption) Order 2025","vi":"Lệnh Thuế thu nhập (Boardroom Pte. Ltd. — Miễn trừ theo Điều 13(12)) 2025","th":"คำสั่งภาษีเงินได้ (Boardroom Pte. Ltd. — การยกเว้นตามมาตรา 13(12)) 2025","id":"Perintah Pajak Penghasilan (Boardroom Pte. Ltd. — Pembebasan menurut Pasal 13(12)) 2025","ms":"Perintah Cukai Pendapatan (Boardroom Pte. Ltd. — Pengecualian menurut Seksyen 13(12)) 2025"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S602-2025","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1942-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Boardroom Pte. Ltd. — Section 13(12) Exemption) Order 2025."}},{"id":"SG-H1942-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Dividend income described in sub-paragraph (2) received in Singapore by Boardroom Pte. Ltd. (a company incorporated in Singapore) on 17 December 2020 from Boardroom Holdings Australia Pty Ltd (a company incorporated in Australia), is exempt from tax.\n(2) Sub-paragraph (1) applies to dividend income that is derived from dividend income received by Boardroom Holdings Australia Pty Ltd from Newreg Pty Ltd (a company incorporated in Australia), which is in turn derived from the profits of Boardroom Pty Ltd (a company incorporated in Australia).\n(3) The exemption in sub-paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 28 August 2025 that is issued on behalf of the Minister for Finance and addressed to Boardroom Business Solutions Pte. Ltd."}}],"pack":"sg-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Boardroom Pte. Ltd. — Section 13(12) Exemption) Order 2025","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1943"] = {"id":"SG-H1943","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S613-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（CapitaLand 商业信托等——第 13(12) 条豁免）命令 2022","en":"Income Tax (CapitaLand Commercial Trust, etc. — Section 13(12) Exemption) Order 2022","orig":"Income Tax (CapitaLand Commercial Trust, etc. — Section 13(12) Exemption) Order 2022","vi":"Lệnh Thuế thu nhập (CapitaLand Commercial Trust, etc. — Miễn trừ theo Điều 13(12)) 2022","th":"คำสั่งภาษีเงินได้ (CapitaLand Commercial Trust, etc. — การยกเว้นตามมาตรา 13(12)) 2022","id":"Perintah Pajak Penghasilan (CapitaLand Commercial Trust, etc. — Pembebasan menurut Pasal 13(12)) 2022","ms":"Perintah Cukai Pendapatan (CapitaLand Commercial Trust, etc. — Pengecualian menurut Seksyen 13(12)) 2022"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S613-2022","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1943-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (CapitaLand Commercial Trust, etc. — Section 13(12) Exemption) Order 2022."}},{"id":"SG-H1943-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Distribution income received in Singapore by HSBC Institutional Trust Services (Singapore) Limited (a company incorporated in Singapore) in its capacity as the trustee of CapitaLand Commercial Trust (a trust constituted in Singapore) from Sentral REIT (formerly known as MRCB‑Quill REIT) (a real estate investment trust listed in Malaysia) on or after 3 November 2020 is exempt from tax.\n(2) Dividend income and interest income received in Singapore by CCT Galaxy One Pte. Ltd. (a company incorporated in Singapore) from Gallileo Property S.a.r.l (a company incorporated in Luxembourg) on or after 3 November 2020 is exempt from tax.\n(3) Dividend income and interest income received in Singapore by CCT Mercury One Pte. Ltd. (a company incorporated in Singapore) from MAC Property Company B.V. and MAC Car Park Company B.V. (companies incorporated in the Netherlands) on or after 3 November 2020 is exempt from tax.\n(4) The exemptions in sub‑paragraphs (1) to (3) are subject to the conditions specified in the letter of approval dated 11 June 2020 addressed to EY Corporate Advisors Pte. Ltd."}}],"pack":"sg-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (CapitaLand Commercial Trust, etc. — Section 13(12) Exemption) Order 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1944"] = {"id":"SG-H1944","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S765-2026?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（CapitaLand 综合商业信托——第 13(12) 条豁免）命令 2026","en":"Income Tax (CapitaLand Integrated Commercial Trust — Section 13(12) Exemption) Order 2026","orig":"Income Tax (CapitaLand Integrated Commercial Trust — Section 13(12) Exemption) Order 2026","vi":"Lệnh Thuế thu nhập (CapitaLand Integrated Commercial Trust — Miễn trừ theo Điều 13(12)) 2026","th":"คำสั่งภาษีเงินได้ (CapitaLand Integrated Commercial Trust — การยกเว้นตามมาตรา 13(12)) 2026","id":"Perintah Pajak Penghasilan (CapitaLand Integrated Commercial Trust — Pembebasan menurut Pasal 13(12)) 2026","ms":"Perintah Cukai Pendapatan (CapitaLand Integrated Commercial Trust — Pengecualian menurut Seksyen 13(12)) 2026"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S765-2026","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1944-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (CapitaLand Integrated Commercial Trust — Section 13(12) Exemption) Order 2026."}},{"id":"SG-H1944-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The following income received in Singapore by HSBC Institutional Trust Services (Singapore) Limited (a company incorporated in Singapore) in its capacity as the trustee of CapitaLand Integrated Commercial Trust (a trust constituted in Singapore) is exempt from tax:\n(a)interest income of $2,122,066 received on 3 March 2026, and interest income received on or after 27 August 2026, from Gallileo Property S.a.r.l (a company incorporated in Luxembourg), that originates from rental and other property‑related income (including capital gain derived from divestment of property) in relation to the property named “Gallileo”, located at Gallusanlage 7/Neckarstrasse 5, 60329 Frankfurt am Main, Germany;\n(b)interest income received on or after 27 August 2026 from MAC Property Company B.V. (a company incorporated in Germany and redomiciled in the Netherlands), that originates from rental and other property‑related income (including capital gain derived from divestment of property) in relation to the property named “Main Airport Center” located at Unterschweinstiege 2‑14, 60549 Frankfurt, Germany;\n(c)interest income received on or after 27 August 2026 from MAC Car Park Company B.V. (a company incorporated in Germany and redomiciled in the Netherlands), that originates from income derived from the operation of the car park situated at the property mentioned in sub‑paragraph (b).\n(2) The exemption in sub-paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 27 August 2026 that is issued on behalf of the Minister for Finance and addressed to EY Corporate Advisors Pte. Ltd."}}],"pack":"sg-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (CapitaLand Integrated Commercial Trust — Section 13(12) Exemption) Order 2026","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
