  FT["SG-H2019"] = {"id":"SG-H2019","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S746-2005?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（外国收入豁免）（第 10 号）命令 2005","en":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2005","orig":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2005","vi":"Lệnh Thuế thu nhập (Miễn trừ thu nhập từ nước ngoài) (Số 10) 2005","th":"คำสั่งภาษีเงินได้ (การยกเว้นรายได้จากต่างประเทศ) (ฉบับที่ 10) 2005","id":"Perintah Pajak Penghasilan (Pembebasan Penghasilan Luar Negeri) (Nomor 10) 2005","ms":"Perintah Cukai Pendapatan (Pengecualian Pendapatan Asing) (No. 10) 2005"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S746-2005","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2019-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) (No. 10) Order 2005."}},{"id":"SG-H2019-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. China Petrotech Holdings Limited is hereby granted exemption from tax on the foreign dividends received in Singapore from the BVI-incorporated company, subject to the conditions specified in the letter of approval dated 31st October 2005 addressed to the tax agent of China Petrotech Holdings Limited."}}],"pack":"sg-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2005","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2020"] = {"id":"SG-H2020","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S730-2013?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（外国收入豁免）（第 10 号）命令 2013","en":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2013","orig":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2013","vi":"Lệnh Thuế thu nhập (Miễn trừ thu nhập từ nước ngoài) (Số 10) 2013","th":"คำสั่งภาษีเงินได้ (การยกเว้นรายได้จากต่างประเทศ) (ฉบับที่ 10) 2013","id":"Perintah Pajak Penghasilan (Pembebasan Penghasilan Luar Negeri) (Nomor 10) 2013","ms":"Perintah Cukai Pendapatan (Pengecualian Pendapatan Asing) (No. 10) 2013"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S730-2013","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2020-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) (No. 10) Order 2013."}},{"id":"SG-H2020-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Pan Pacific Hotels Group Limited is hereby granted exemption from tax on the dividends received in Singapore —\n(a)on 22nd June 2012;\n(b)on 26th December 2012;\n(c)on 12th April 2013; and\n(d)on or after 17th October 2013,\nfrom HPL Properties (Malaysia) Sdn Bhd, a company located in Malaysia.\n(2) The exemption under sub‑paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 17th October 2013 addressed to Pan Pacific Hotels Group Limited."}}],"pack":"sg-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2013","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2021"] = {"id":"SG-H2021","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S592-2017?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（外国收入豁免）（第 10 号）命令 2017","en":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2017","orig":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2017","vi":"Lệnh Thuế thu nhập (Miễn trừ thu nhập từ nước ngoài) (Số 10) 2017","th":"คำสั่งภาษีเงินได้ (การยกเว้นรายได้จากต่างประเทศ) (ฉบับที่ 10) 2017","id":"Perintah Pajak Penghasilan (Pembebasan Penghasilan Luar Negeri) (Nomor 10) 2017","ms":"Perintah Cukai Pendapatan (Pengecualian Pendapatan Asing) (No. 10) 2017"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S592-2017","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2021-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Exemption of Foreign Income) (No. 10) Order 2017."}},{"id":"SG-H2021-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Subject to sub-paragraphs (2) and (3), Wan Hai International Pte. Ltd. (a company incorporated in Singapore) is granted exemption from tax on the dividends received in Singapore from Wan Hai Lines (United Arab Emirates) LLC (a company incorporated in the United Arab Emirates).\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in all of the following letters issued by the Maritime and Port Authority of Singapore and addressed to Wan Hai International Pte. Ltd.:\n(a)the letter of approval relating to the award of Approved Network Company status under the Approved Shipping Logistics Enterprise Scheme dated 29 March 2007;\n(b)the letter of approval relating to the extension of the status under the Approved Shipping Logistics Enterprise Scheme dated 9 January 2009;\n(c)the letter referring to the grant of the Maritime Sector Incentive — Shipping-Related Support Services Award dated 2 June 2011.\n(3) The exemption applies to dividends received in Singapore between 1 January 2007 and the earliest of the following dates (both dates inclusive):\n(a)31 May 2016;\n(b)if, before 1 June 2011, Wan Hai International Pte. Ltd.’s approval as a development and expansion company under Part IIIB (Development and Expansion Incentive) of the Economic Expansion Incentives (Relief from Income Tax) Act (Cap. 86) has been revoked or withdrawn, the date immediately preceding the date of the revocation or withdrawal;\n(c)if, on or after 1 June 2011, Wan Hai International Pte. Ltd.’s approval as an approved company under section 43ZF of the Act has been revoked or withdrawn, the date immediately preceding the date of the revocation or withdrawal;\n(d)if Wan Hai Lines (United Arab Emirates) LLC’s status as an approved network company of Wan Hai International Pte. Ltd. has been revoked or withdrawn, the date immediately preceding the date of the revocation or withdrawal."}}],"pack":"sg-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Foreign Income) (No. 10) Order 2017","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
